/**
 * He gives up the national captaincy (or vice-captaincy). The selectors do not name him again until he asks them to (Career > Captaincy), so
 * [captaincy] leaves him alone while [CareerProfile.nationalRoleLeft] is set. What he gave up and for which country is kept ("Captain|India").
 */
fun stepDown(career: CareerProfile): Captaincy {
    val role = career.nationalRole ?: return Captaincy(career, "")
    return Captaincy(
        career.copy(nationalRole = null, nationalRoleLeft = "$role|${career.nation}"),
        "You have given up the ${role.lowercase()} of ${career.nation}. You can ask the selectors for it back on the Captaincy page."
    )
}

/** He asks for the role back: given if he is still in the squad of the same country and the selectors still rate his leadership (the score that keeps a captain). */
fun takeBack(career: CareerProfile): Captaincy {
    val saved = career.nationalRoleLeft ?: return Captaincy(career, "")
    val role = saved.substringBefore("|")
    if (!career.isInternational || saved.substringAfter("|") != career.nation) return Captaincy(career, "You are not in that national squad any more.")
    if (leadershipScore(career) < 3.0) {
        return Captaincy(career, "The selectors do not want you as ${role.lowercase()} again yet: they want more matches and better form.")
    }
    return Captaincy(career.copy(nationalRole = role, nationalRoleLeft = null), "The selectors give you back the ${role.lowercase()} of ${career.nation}.")
}

/** A sentence for the Career tab and the pathway about the national captaincy. */

// ------------------------------------------------------------ giving up and taking back a franchise captaincy (part twenty-nine)

/** The franchises he captains this season (the one saved the old way included). */
fun captainedTeams(career: CareerProfile): List<String> =
    if (career.leagueDecidedSeason == career.season) (career.leagueCaptainTeamIds.orEmpty() + listOfNotNull(career.leagueCaptainTeamId)).distinct() else emptyList()

/** He gives up the captaincy of ONE franchise: he stays captain of the others, and may take this one back. */
fun stepDownFrom(career: CareerProfile, teamId: String): CareerProfile = career.copy(
    leagueCaptainTeamIds = captainedTeams(career).filter { it != teamId },
    leagueCaptainTeamId = null,
    leagueCaptainLeft = (career.leagueCaptainLeft.orEmpty() + teamId).distinct()
)

/** He takes the captaincy of a franchise back (only one he gave up this season). */
fun takeBackCaptaincy(career: CareerProfile, teamId: String): CareerProfile = career.copy(
    leagueCaptainTeamIds = (captainedTeams(career) + teamId).distinct(),
    leagueCaptainTeamId = null,
    leagueCaptainLeft = career.leagueCaptainLeft.orEmpty().filter { it != teamId }
)

// ------------------------------------------------------------ selection for a match

/** The best-rated player of a team other than the career player: the one who becomes captain when he steps down. */
fun nextCaptainName(state: TournamentState, career: CareerProfile, teamId: String): String? {
    val team = state.teams.find { it.id == teamId } ?: return null
    val pid = CareerDomestic.playerId(career.id)
    return team.players.filter { it.id != pid }.maxByOrNull { maxOf(it.battingRating, it.bowlingRating) + it.fieldingRating * 0.1 }?.name
}

/**
 * Names the captain and vice-captain of the player's XI for a career match (part twenty-nine). He is the captain only where he really is one (the club, the state
 * squad, the nation or that franchise); otherwise (a vice-captain, a player, or a captain who stepped down) the best-rated other player is captain, and the next best
 * vice-captain (the career player himself when he is the vice-captain here), so the side always has a captain and the scorecards and Match info name him.
 */
fun withLeaders(xi: Team, career: CareerProfile, state: TournamentState): Team {
    val pid = playerIdIn(state, career)
    val me = xi.players.find { it.id == pid }
    val others = xi.players.filter { it.id != pid }.sortedByDescending { maxOf(it.battingRating, it.bowlingRating) + it.fieldingRating * 0.1 }
    val iLead = me != null && captainIn(career, state)
    val iVice = me != null && !iLead && when {
        isClub(state) -> career.leadership == CareerLeadership.VICE && !career.isState && !career.isInternational
        CareerInternational.isInternational(state) -> career.nationalRole == "Vice-captain"
        CareerLeagues.isLeague(state) -> false
        else -> career.stateRole == CareerLeadership.VICE
    }
    val captain = if (iLead) me else others.firstOrNull()
    val vice = if (iVice) me else others.firstOrNull { it.id != captain?.id }
    return xi.copy(captainId = captain?.id, viceCaptainId = vice?.id)
}

fun nameOf(state: TournamentState, teamId: String?): String = state.teams.find { it.id == teamId }?.name ?: "?"

